[70503]={title="橡胶果实",voice="我是要成为海贼王的男人！",story="小时候因误食了橡胶果实（人人果实·幻兽种·尼卡形态），而获得了如橡胶般自由伸缩的能力 。在香克斯的启蒙下，萌生了找到传说中的One Piece，成为海贼王的梦想 。口头禅是“我是要成为海贼王的男人”",has_art=true},
[70504]={title="人人果实·幻兽种·尼卡形态",voice="任何人都不许伤害我的伙伴！",story="人人果实·幻兽种·尼卡形态的最终形态，借此形态打败了四皇之一的凯多",has_art=true},
[70505]={title="鱼鱼果实·幻兽种·青龙形态",voice="我才是最强的男人！！！",story="，百兽海贼团总督，原新世界的“四皇”之一，被蒙奇·D·路飞击败后被剥夺四皇称号。实力极其强悍，拥有超乎想象的防御力和生命力，被称为“最强的生物”",has_art=true},
[70506]={title="人人果实·幻兽种·大佛形态",voice="君临于世的正义",story="原海军本部元帅，动物系人人果实·幻兽种·大佛形态能力者，拥有三色霸气，顶上战争后辞去了元帅的职位。两年后在德雷斯罗萨再登场，协助缉押天夜叉唐吉诃德·多弗朗明哥。",has_art=true},
[70507]={title="传说大海贼",voice="我才是传说中的大海贼！",story="金狮子”史基，飘飘果实能力者，飘浮人，能浮游自己或物件在空中飞行，而得到“飞天海贼”（空飞ぶ海贼）的绰号，但对除了自己以外的生命体都不起作用。飞空海贼团船长－金狮子海贼舰队提督，是曾与哥尔·D·罗杰和“白胡子”爱德华·纽盖特齐名的传说中的大海贼。同时是推进城历史上第一位逃脱的海贼。持有的两把名剑“樱十”和“木枯”",has_art=true},
[70508]={title="超人系·重重果实",voice="我将击败所有黑暗！",story="一生参加了世界征兵两年间通过“世界征兵”被破格提拔为海军大将，代号“藤虎”。与绿牛、黄猿，并称为新的三大将。",has_art=true},
[70509]={title="科学家",voice="成为我的研究样品吧！",story="原科研团队MADS以及世界政府科学班成员，曾与贝加庞克共事，在科学班排名第二，被称为“大规模杀戮武器的最高权威”。后来因爆炸事故被捕，逃走后来到庞克哈萨德进行秘密研究。自然系恶魔果实瓦斯果实能力者。悬赏金3亿贝里。",has_art=true},
[70510]={title="四皇",voice="你们才是旧时代的残党，哈哈哈哈哈~~~~~",story="黑胡子在顶山战争中夺取了白胡子的震震果实，成功的成为了新世界四皇之一。",has_art=true},
[70511]={title="外骨骼",voice="没有任何攻击能对我造成伤害！",story="外骨骼使得山治的身体变得坚韧无比，拥有超人般的恢复力。可以让山治受伤和骨折的身体高速复原，并且提升肉体硬度，以达到刀枪不入的境界",has_art=true},
[70512]={title="猫蝮蛇老大",voice="老子就是鲸鱼森林守护神",story="猫种毛皮族，佐乌岛毛茸茸公国两位国王之一，是掌管着黑夜的“黑夜之王”，与白昼之王犬岚齐名，被称为“猫蝮蛇老大”，自称“老子”。活跃时间为晚上六点至早上六点，其他时间都会陷入沉睡。猫蝮蛇率领着手下的“侠客团”，一起守护着毛皮族圣地“鲸鱼森林”，被称为“鲸鱼森林守护神”  。与犬岚过去同是和之国九里大名光月御田的家臣，赤鞘九人男之一，曾随御田加入过白胡子海贼团以及罗杰海贼团。御田死后，回到毛茸茸公国，以黑夜之王的身份治理毛茸茸公国",has_art=true},
[70513]={title="五老星(土星)",voice="妄想挑战世界政府，就是死路一条",story="世界贵族“天龙人”，外界所认知的世界政府最高权力“五老星”中的科学防卫武神，受到伊姆的直接管辖。",has_art=true},
[70514]={title="女帝",voice="路飞，等等妾身",story="海贼女帝。是位于无风带九蛇岛的海贼国家亚马逊·百合王国的现任皇帝，同时也是九蛇海贼团的现任船长，其绝世的容颜被世人评价为“世界第一美女”。曾是为政府服务王下七武海的成员之一。在王下七武海制度废除后，被海军追捕。",has_art=true},
[70515]={title="饼干将星",voice="甜点三将星",story="四皇之一“BIG MOM”夏洛特·玲玲的第十子（第15个孩子），与第六女夏洛特·卡斯塔德、第七女夏洛特·安洁露是龙凤胎。BIG MOM海贼团的最高干部“甜点三将星”之一，托特兰王国的饼干大臣，驻地是饼干岛的曲奇镇 [4] 。超人系恶魔果实饼干果实能力者，饼干人，悬赏金为8亿6000万贝里。平时藏在制造的饼干战士之中，自称“饼干骑士”，因此大多数人都不知道他的真面目，以至于悬赏令上的肖像画都是饼干战士",has_art=true},
[70516]={title="十四女-将星-夏洛特·斯慕吉",voice="甜点三将星",story="原四皇之一的“BIG MOM”夏洛特·玲玲的第14个女儿，即第35个孩子，与15女夏洛特·斯特隆、16女夏洛特·斯纳蒙是三胞胎，足长族混血。BIG MOM海贼团的最高干部“甜点三将星”之一，万国的果汁大臣，驻地是100%岛果树镇。超人系恶魔果实榨榨果实能力者，脱水人，悬赏金为9亿3200万贝里，拥有超高战斗天分 [3]。夏洛特家族最受欢迎的姐姐排行榜第1名 [5]。拥有带有自己头像的分舰。其率领的舰队上搭乘着BIG MOM的许多女儿",has_art=true},
