[70519]={title="狙击王",voice="美女剑豪带着肉来了！",story="乌索普出生于东海西罗布村，父亲是红发海贼团的狙击手耶稣布。小时候，他和村里的几个孩子组成了“乌索普海贼团”。17岁时，为了成为勇敢的海上战士加入草帽一伙，是草帽一伙的第三人，第四位加入的成员，在水之都因分歧而退出，司法岛事件结束后重新加入",has_art=true},
